<div class="page-heading"><div><span class="section-kicker">YOUR ACCOUNT</span><h1>Account settings</h1><p>Manage your password and keep your account secure.</p></div></div><div class="row g-4"><div class="col-lg-4"><section class="card"><div class="profile-summary"><span class="avatar avatar-xl"><?= e(mb_substr($user['name'],0,1)) ?></span><h2><?= e($user['name']) ?></h2><p><?= e($user['email']) ?></p><?= badge($user['role']) ?></div></section></div><div class="col-lg-8"><section class="card"><div class="card-header"><h2 class="card-title">Change password</h2></div><div class="card-body"><form action="<?= e(base_url('index.php')) ?>" method="post"><?= csrf() ?><input type="hidden" name="_action" value="password_change"><input type="hidden" name="_return" value="account"><?= input('current_password','Current password','','password',true,'autocomplete="current-password"') ?><?= input('password','New password','','password',true,'minlength="12" maxlength="128" autocomplete="new-password"') ?><?= input('password_confirmation','Confirm new password','','password',true,'minlength="12" maxlength="128" autocomplete="new-password"') ?><p class="small text-secondary">Use at least 12 characters. Changing your password signs out your other sessions.</p><button class="btn btn-primary">Update password</button></form></div></section></div></div>

